+#[cfg(test)]
+mod tests {
+    use super::normalize_tool_call_arguments;
+
+    fn make_tool_call_messages(arguments: &str) -> serde_json::Value {
+        serde_json::json!([{
+            "role": "assistant",
+            "tool_calls": [{
+                "id": "call_1",
+                "type": "function",
+                "function": { "name": "f", "arguments": arguments }
+            }]
+        }])
